--
-- Tablo için tablo yapısı `iletisim_ayarlari`
--

CREATE TABLE `iletisim_ayarlari` (
  `id` int(11) NOT NULL,
  `telefon` varchar(50) DEFAULT NULL,
  `telefon2` varchar(50) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `email2` varchar(100) DEFAULT NULL,
  `adres_tr` text DEFAULT NULL,
  `adres_dari` text DEFAULT NULL,
  `calisma_saatleri` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`calisma_saatleri`)),
  `sosyal_medya` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`sosyal_medya`)),
  `harita_embed` text DEFAULT NULL,
  `istatistikler` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`istatistikler`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Tablo döküm verisi `iletisim_ayarlari`
