INSERT INTO `iletisim_faq` (`id`, `soru_tr`, `soru_dari`, `cevap_tr`, `cevap_dari`, `sira`, `aktif`, `created_at`) VALUES
(1, 'Nasıl ilan veririm?', 'چگونه آگهی ثبت کنم؟', 'İlan Ver butonuna tıklayın, formu doldurun ve fotoğraflarınızı yükleyin.', 'روی دکمه \"ثبت آگهی\" کلیک کنید، فرم را پر کنید و عکس‌ها را آپلود کنید. آگهی شما پس از تایید منتشر می‌شود.', 1, 1, '2025-12-03 08:29:21'),
(2, 'İlan vermek ücretsiz mi?', 'آیا ثبت آگهی رایگان است؟', 'Evet! İlan vermek tamamen ücretsizdir. Premium paketlerle ilanınızı öne çıkarabilirsiniz.', 'بله! ثبت آگهی کاملاً رایگان است. اما می‌توانید با پکیج‌های پریمیوم، آگهی خود را ویژه کنید.', 2, 1, '2025-12-03 08:29:21'),
(3, 'Nasıl mağaza açarım?', 'چگونه مغازه باز کنم؟', 'Mağaza Aç bölümüne gidin, bilgilerinizi girin ve paket seçin. Basic paket ücretsizdir!', 'روی \"افتتاح مغازه\" کلیک کنید، اطلاعات را وارد کنید و پکیج مناسب را انتخاب کنید. مغازه Basic رایگان است!', 3, 1, '2025-12-03 08:29:21'),
(4, 'Ne kadar sürede cevap alırım?', 'چند وقت طول می‌کشد تا پاسخ بگیرم؟', 'Destek ekibimiz genellikle 2 saat içinde (çalışma saatlerinde) yanıt verir.', 'تیم پشتیبانی ما معمولاً در کمتر از ۲ ساعت (در ساعات کاری) پاسخ می‌دهد. در مواقع اضطراری تماس بگیرید.', 4, 1, '2025-12-03 08:29:21'),
(5, 'Nasıl ilan veririm?', 'چگونه آگهی ثبت کنم؟', 'İlan Ver butonuna tıklayın, formu doldurun ve fotoğraflarınızı yükleyin.', 'روی دکمه \"ثبت آگهی\" کلیک کنید، فرم را پر کنید و عکس‌ها را آپلود کنید. آگهی شما پس از تایید منتشر می‌شود.', 1, 1, '2025-12-03 08:29:41'),
(6, 'İlan vermek ücretsiz mi?', 'آیا ثبت آگهی رایگان است؟', 'Evet! İlan vermek tamamen ücretsizdir. Premium paketlerle ilanınızı öne çıkarabilirsiniz.', 'بله! ثبت آگهی کاملاً رایگان است. اما می‌توانید با پکیج‌های پریمیوم، آگهی خود را ویژه کنید.', 2, 1, '2025-12-03 08:29:41'),
