CREATE TABLE `magazalar` (
  `id` int(11) NOT NULL,
  `kullanici_id` int(11) NOT NULL,
  `ad` varchar(255) NOT NULL,
  `ad_dari` varchar(255) DEFAULT NULL,
  `slug` varchar(255) NOT NULL,
  `custom_url` varchar(255) DEFAULT NULL,
  `aciklama` text DEFAULT NULL,
  `logo` longtext DEFAULT NULL,
  `kapak_resmi` longtext DEFAULT NULL,
  `banner` longtext DEFAULT NULL,
  `tema_renk` varchar(50) DEFAULT '#3B82F6',
  `telefon` varchar(20) DEFAULT NULL,
  `adres` text DEFAULT NULL,
  `il_id` varchar(100) DEFAULT NULL,
  `store_level` enum('basic','pro','elite') DEFAULT 'basic',
  `vitrin_oncelik` int(11) DEFAULT NULL COMMENT 'Vitrin önceliği (NULL=vitrinde değil, 1-999=öncelik sırası)',
  `paket_baslangic` timestamp NULL DEFAULT NULL,
  `paket_bitis` timestamp NULL DEFAULT NULL,
  `product_limit` int(11) DEFAULT 50,
  `category_limit` int(11) DEFAULT 1,
  `listing_priority` int(11) DEFAULT 0,
  `search_weight` decimal(3,1) DEFAULT 1.0,
  `analytics_access` enum('basic','intermediate','advanced') DEFAULT 'basic',
  `theme` enum('default','customizable','premium') DEFAULT 'default',
  `listing_discount` int(11) DEFAULT 0,
  `bulk_upload` tinyint(1) DEFAULT 0,
  `support_level` enum('normal','fast','vip') DEFAULT 'normal',
  `homepage_vip_slot` tinyint(1) DEFAULT 0,
  `weekly_auto_feature` tinyint(1) DEFAULT 0,
  `monthly_ad_credit` decimal(10,2) DEFAULT 0.00,
  `video_upload` tinyint(1) DEFAULT 0,
  `custom_branding` tinyint(1) DEFAULT 0,
  `verification_status` enum('none','basic','business') DEFAULT 'none',
  `verification_badge` tinyint(1) DEFAULT 0,
  `aktif` tinyint(1) DEFAULT 1,
  `onay_durumu` enum('beklemede','onaylandi','reddedildi') DEFAULT 'beklemede',
  `goruntulenme` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `ortalama_puan` decimal(2,1) DEFAULT 0.0,
  `toplam_yorum` int(11) DEFAULT 0,
  `guvenilir_satici` tinyint(1) DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

