--
-- Tetikleyiciler `magaza_yorumlar`
--
DELIMITER $$
CREATE TRIGGER `magaza_yorum_after_delete` AFTER DELETE ON `magaza_yorumlar` FOR EACH ROW BEGIN
  UPDATE magazalar 
  SET 
    ortalama_puan = (
      SELECT COALESCE(AVG(puan), 0) 
      FROM magaza_yorumlar 
      WHERE magaza_id = OLD.magaza_id AND aktif = TRUE AND onaylandi = TRUE
    ),
    toplam_yorum = (
      SELECT COUNT(*) 
      FROM magaza_yorumlar 
      WHERE magaza_id = OLD.magaza_id AND aktif = TRUE AND onaylandi = TRUE
    )
  WHERE id = OLD.magaza_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `magaza_yorum_after_insert` AFTER INSERT ON `magaza_yorumlar` FOR EACH ROW BEGIN
  IF NEW.aktif = TRUE AND NEW.onaylandi = TRUE THEN
    UPDATE magazalar 
    SET 
      ortalama_puan = (
        SELECT COALESCE(AVG(puan), 0) 
        FROM magaza_yorumlar 
        WHERE magaza_id = NEW.magaza_id AND aktif = TRUE AND onaylandi = TRUE
      ),
      toplam_yorum = (
        SELECT COUNT(*) 
        FROM magaza_yorumlar 
        WHERE magaza_id = NEW.magaza_id AND aktif = TRUE AND onaylandi = TRUE
      )
    WHERE id = NEW.magaza_id;
  END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `magaza_yorum_after_update` AFTER UPDATE ON `magaza_yorumlar` FOR EACH ROW BEGIN
  UPDATE magazalar 
  SET 
    ortalama_puan = (
      SELECT COALESCE(AVG(puan), 0) 
      FROM magaza_yorumlar 
      WHERE magaza_id = NEW.magaza_id AND aktif = TRUE AND onaylandi = TRUE
    ),
    toplam_yorum = (
      SELECT COUNT(*) 
      FROM magaza_yorumlar 
      WHERE magaza_id = NEW.magaza_id AND aktif = TRUE AND onaylandi = TRUE
    )
  WHERE id = NEW.magaza_id;
END
$$
DELIMITER ;

