--
-- Tablo için tablo yapısı `paketler`
--

CREATE TABLE `paketler` (
  `id` int(11) NOT NULL,
  `ad` varchar(100) NOT NULL,
  `ad_dari` varchar(100) DEFAULT NULL,
  `store_level` enum('basic','pro','elite') NOT NULL,
  `sure_ay` int(11) NOT NULL,
  `fiyat` decimal(10,2) NOT NULL,
  `product_limit` int(11) DEFAULT 50,
  `category_limit` int(11) DEFAULT 1,
  `listing_priority` int(11) DEFAULT 0,
  `search_weight` decimal(3,1) DEFAULT 1.0,
  `ozellikler` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`ozellikler`)),
  `analytics_access` varchar(50) DEFAULT 'basic',
  `theme` varchar(50) DEFAULT 'default',
  `listing_discount` int(11) DEFAULT 0,
  `bulk_upload` tinyint(1) DEFAULT 0,
  `support_level` varchar(50) DEFAULT 'normal',
  `homepage_vip_slot` tinyint(1) DEFAULT 0,
  `weekly_auto_feature` tinyint(1) DEFAULT 0,
  `monthly_ad_credit` decimal(10,2) DEFAULT 0.00,
  `video_upload` tinyint(1) DEFAULT 0,
  `custom_url` tinyint(1) DEFAULT 0,
  `custom_branding` tinyint(1) DEFAULT 0,
  `verification_badge` tinyint(1) DEFAULT 0,
  `aktif` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `eski_fiyat` decimal(10,2) DEFAULT NULL COMMENT 'Eski fiyat (indirimden önceki fiyat) - üzeri çizili gösterilir'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

