INSERT INTO `paketler` (`id`, `ad`, `ad_dari`, `store_level`, `sure_ay`, `fiyat`, `product_limit`, `category_limit`, `listing_priority`, `search_weight`, `ozellikler`, `analytics_access`, `theme`, `listing_discount`, `bulk_upload`, `support_level`, `homepage_vip_slot`, `weekly_auto_feature`, `monthly_ad_credit`, `video_upload`, `custom_url`, `custom_branding`, `verification_badge`, `aktif`, `created_at`, `updated_at`, `eski_fiyat`) VALUES
(2, 'Pro Store - Monthly', 'بسته پرو - ماهانه', 'pro', 1, 150.00, 200, 3, 1, 1.5, '{\"aciklama\":\"بسته پرو مخصوص فروشندگان حرفه‌ای است که می‌خواهند دیده‌شدن بیشتری داشته باشند. با محدودیت‌های بالاتر، ابزارهای تحلیل پیشرفته، طراحی قابل شخصی‌سازی و اولویت در نمایش محصولات، فروش شما به‌طور قابل توجهی افزایش می‌یابد.\",\"ozellikler\":[\"حداکثر ۲۰۰ محصول\",\"تا ۳ دسته‌بندی\",\"اولویت Pro در جستجو\",\"+۵۰٪ افزایش دیده شدن\",\"گزارشات پیشرفته\",\"سفارشی‌سازی قالب (کاور، بنر، رنگ)\",\"۲۵٪ تخفیف تبلیغات\",\"بارگذاری دسته‌ای (CSV/Excel)\",\"سیستم نظرات و امتیاز فعال\",\"نمایش تخفیف محصولات\",\"پشتیبانی سریع (۱۲ ساعت)\"]}', 'intermediate', 'customizable', 25, 1, 'fast', 0, 0, 0.00, 0, 0, 0, 0, 1, '2025-11-28 22:41:55', '2025-12-01 21:34:10', 350.00),
(3, 'Pro Store - 3 Months', 'بسته پرو - ۳ ماهه', 'pro', 3, 350.00, 200, 3, 1, 1.5, '{\"aciklama\":\"بسته پرو مخصوص فروشندگان حرفه‌ای است که می‌خواهند دیده‌شدن بیشتری داشته باشند. با محدودیت‌های بالاتر، ابزارهای تحلیل پیشرفته، طراحی قابل شخصی‌سازی و اولویت در نمایش محصولات، فروش شما به‌طور قابل توجهی افزایش می‌یابد.\",\"ozellikler\":[\"همه امکانات Pro\",\"۳۰٪ تخفیف قیمت\",\"صرفه‌جویی ۳۱۵ افغانی\",\"قیمت عادی: ۱٬۰۵۰ افغانی\",\"قیمت با تخفیف: ۷۳۵ افغانی\"]}', 'intermediate', 'customizable', 25, 1, 'fast', 0, 0, 0.00, 0, 0, 0, 0, 1, '2025-11-28 22:41:55', '2025-12-01 21:36:05', 700.00),
(4, 'Elite Store - Monthly', 'بسته پریمیوم - ماهانه', 'elite', 3, 570.00, 999999, 999, 2, 2.0, '{\"aciklama\":\"بسته پریمیوم سطحی ویژه برای فروشندگان بزرگ و برندها است. با امکانات نامحدود، ویترین اختصاصی، تحلیل‌های پیشرفته، پشتیبانی VIP و ابزارهای حرفه‌ای، فروشگاه شما به یک فروشگاه واقعی و قدرتمند آنلاین تبدیل می‌شود.\",\"ozellikler\":[\"محصول نامحدود\",\"دسته‌بندی نامحدود\",\"ویترین ثابت صفحه اصلی\",\"بالاترین اولویت جستجو (x۲)\",\"تبلیغ هفتگی رایگان\",\"۵۰۰ افغانی اعتبار تبلیغاتی\",\"قالب اختصاصی Premium\",\"آدرس اختصاصی مغازه\",\"تحلیل‌های حرفه‌ای (Heatmap)\",\"ارسال پیام دسته‌ای\",\"اتوماسیون کامل (موجودی، قیمت)\",\"لوگو و برندینگ کامل\",\"نشان تأیید کسب‌وکار\",\"ویدیو نامحدود\",\"نمایش تخفیف محصولات\",\"پشتیبانی VIP (۲۴/۷)\"]}', 'advanced', 'premium', 0, 1, 'vip', 1, 1, 500.00, 1, 1, 1, 1, 1, '2025-11-28 22:41:55', '2025-12-01 21:36:36', 900.00),
(5, 'Elite Store - 3 Months', 'بسته پریمیوم - ۳ ماهه', 'elite', 3, 1197.00, 999999, 999, 2, 2.0, '{\"aciklama\": \"بسته پریمیوم سطحی ویژه برای فروشندگان بزرگ و برندها است. با امکانات نامحدود، ویترین اختصاصی، تحلیل‌های پیشرفته، پشتیبانی VIP و ابزارهای حرفه‌ای، فروشگاه شما به یک فروشگاه واقعی و قدرتمند آنلاین تبدیل می‌شود.\", \"ozellikler\": [\"همه امکانات Elite\", \"۳۰٪ تخفیف قیمت\", \"صرفه‌جویی ۵۱۳ افغانی\", \"قیمت عادی: ۱٬۷۱۰ افغانی\", \"قیمت با تخفیف: ۱٬۱۹۷ افغانی\", \"۱٬۵۰۰ افغانی اعتبار تبلیغاتی\"]}', 'advanced', 'premium', 0, 1, 'vip', 1, 1, 1500.00, 1, 1, 1, 1, 1, '2025-11-28 22:41:55', '2025-11-29 15:58:15', 1710.00),
(6, 'Basic Store', 'بسته عادی', 'basic', 3, 0.00, 50, 3, 0, 1.0, '{\"aciklama\":\"بسته عادی برای فروشندگان تازه‌کار و شروع سریع در بازار وطن طراحی شده است. با امکانات ضروری، محدودیت مناسب و مدیریت آسان، می‌توانید محصولات خود را بدون هزینه به خریداران معرفی کنید.\",\"ozellikler\":[\"رایگان - بدون هزینه\",\"محدودیت ۵۰ محصول\",\"فقط ۱ دسته‌بندی\",\"لیست استاندارد\",\"تم پیش‌فرض\",\"آمار پایه\",\"پیام‌رسانی عادی\"]}', 'basic', 'default', 0, 0, 'normal', 0, 0, 0.00, 0, 0, 0, 0, 1, '2025-11-28 22:50:43', '2025-12-01 21:37:15', 50.00);

