--
-- Tablo için tablo yapısı `reklamlar`
--

CREATE TABLE `reklamlar` (
  `id` int(11) NOT NULL,
  `baslik` varchar(255) NOT NULL,
  `aciklama` text DEFAULT NULL,
  `reklam_turu` enum('banner_header','banner_kategori','banner_arama','sponsorlu_magaza','sponsorlu_urun') NOT NULL,
  `banner_url` longtext DEFAULT NULL COMMENT 'Reklam banner resmi (base64 veya URL)',
  `hedef_url` text DEFAULT NULL COMMENT 'Reklam hedef linki',
  `ilan_id` int(11) DEFAULT NULL,
  `magaza_id` int(11) DEFAULT NULL,
  `kategori_id` int(11) DEFAULT NULL,
  `konum` varchar(100) DEFAULT NULL,
  `boyut` varchar(50) DEFAULT NULL,
  `baslangic_tarihi` timestamp NOT NULL DEFAULT current_timestamp(),
  `bitis_tarihi` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `butce` decimal(10,2) DEFAULT NULL,
  `tiklanma` int(11) DEFAULT 0,
  `goruntulenme` int(11) DEFAULT 0,
  `aktif` tinyint(1) DEFAULT 1,
  `onay_durumu` enum('beklemede','onaylandi','reddedildi') DEFAULT 'beklemede',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

